BEGIN;
CREATE TABLE contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),contact_list_id uuid NOT NULL REFERENCES contact_lists(id),external_id text,phone_e164 text NOT NULL,timezone text,consent_reference text,dnc boolean NOT NULL DEFAULT false,attributes jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(contact_list_id,phone_e164));
CREATE TABLE campaign_call_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),campaign_id uuid NOT NULL REFERENCES campaigns(id),contact_id uuid NOT NULL REFERENCES contacts(id),state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','policy_review','ready','leased','dialing','ringing','answered','wrap_up','completed','retry','failed','cancelled')),priority integer NOT NULL DEFAULT 100,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),max_attempts integer NOT NULL DEFAULT 3 CHECK(max_attempts BETWEEN 1 AND 20),available_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_until timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,contact_id));
CREATE INDEX campaign_call_jobs_claim_idx ON campaign_call_jobs(campaign_id,state,available_at,priority,created_at);
ALTER TABLE contacts ENABLE ROW LEVEL SECURITY;ALTER TABLE contacts FORCE ROW LEVEL SECURITY;ALTER TABLE campaign_call_jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE campaign_call_jobs FORCE ROW LEVEL SECURITY;
CREATE POLICY contacts_isolation ON contacts USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY campaign_call_jobs_isolation ON campaign_call_jobs USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
